          <p v-if="overlapWarning" class="alert error full">{{ overlapWarning }}</p><p v-else-if="insufficientWarning" class="alert error full">{{ insufficientWarning }}</p><p v-else class="muted full">Le nombre définitif de jours est recalculé par le serveur selon le planning et les jours fériés.</p>
          <div class="actions full"><button class="button primary" :disabled="busy || !form.typeCongeId || !!overlapWarning || !!insufficientWarning">Créer le brouillon</button></div>
        </form></article>
        <article class="card"><h3>Mes absences</h3><div class="table-wrap"><table><thead><tr><th>Période</th><th>Type</th><th>Statut</th><th>Justificatif</th></tr></thead><tbody><tr v-for="a in absences" :key="a.id"><td>{{ date(a.date_debut) }} – {{ date(a.date_fin) }}</td><td>{{ a.type }}</td><td>{{ a.statut }}</td><td><label class="upload-link">Déposer<input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="uploadEvidence(a,$event)"></label></td></tr><tr v-if="!absences.length"><td colspan="4" class="empty">Aucune absence enregistrée.</td></tr></tbody></table></div></article>
      </div>
      <article class="card"><div class="section-heading"><h3>Mes demandes</h3><label>Année <input type="number" v-model.number="year" @change="loadMine" min="2000"></label></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Période</th><th>Jours</th><th>Statut</th><th>Historique</th><th>Actions</th></tr></thead><tbody><tr v-for="d in requests" :key="d.id"><td>{{ d.type_libelle }}</td><td>{{ date(d.date_debut) }} – {{ date(d.date_fin) }}</td><td>{{ number(d.nb_jours) }}</td><td><span class="badge">{{ d.statut }}</span></td><td>{{ history(d) }}</td><td><div class="row-actions"><button v-if="d.statut==='BROUILLON'" class="button" @click="submitRequest(d)">Soumettre</button><button v-if="['SOUMISE','VALIDEE_MANAGER'].includes(d.statut)" class="danger-link" @click="cancelRequest(d)">Annuler</button></div></td></tr><tr v-if="!requests.length"><td colspan="6" class="empty">Aucune demande pour cette année.</td></tr></tbody></table></div></article>
    </template>

    <template v-if="active==='approvals'">
      <article class="card"><h3>{{ isManager ? 'Demandes de mon équipe' : 'File de validation RH' }}</h3><div class="table-wrap"><table><thead><tr><th>Salarié</th><th>Type et période</th><th>Jours</th><th>Contexte</th><th>Statut</th><th>Décision</th></tr></thead><tbody><tr v-for="d in approvals" :key="d.id"><td>{{ d.employe_prenom }} {{ d.employe_nom }}</td><td>{{ d.type_libelle }}<br><small>{{ date(d.date_debut) }} – {{ date(d.date_fin) }}</small></td><td>{{ number(d.nb_jours) }}</td><td><button class="link-button" @click="showRequestContext(d)">Solde · absences · calendrier</button></td><td>{{ d.statut }}</td><td><div class="row-actions"><button class="button primary" @click="approve(d)">{{ isManager ? 'Valider manager' : 'Valider RH' }}</button><button class="danger-link" @click="reject(d)">Refuser</button></div></td></tr><tr v-if="!approvals.length"><td colspan="6" class="empty">Aucune demande en attente.</td></tr></tbody></table></div>
        <article v-if="contextRequest" class="card inset"><div class="section-heading"><h3>Contexte · {{ contextRequest.employe_prenom }} {{ contextRequest.employe_nom }}</h3><button class="link-button" @click="contextRequest=null">Fermer</button></div><p><strong>{{ contextRequest.type_libelle }}</strong> · {{ date(contextRequest.date_debut) }} – {{ date(contextRequest.date_fin) }} · {{ number(contextRequest.nb_jours) }} jour(s)</p><h4>Soldes par type</h4><div class="table-wrap"><table><thead><tr><th>Type</th><th>Acquis</th><th>Pris</th><th>En attente</th><th>Restant</th></tr></thead><tbody><tr v-for="s in contextBalances" :key="s.id"><td>{{ s.libelle }}</td><td>{{ number(s.acquis) }}</td><td>{{ number(s.pris) }}</td><td>{{ number(s.enAttente) }}</td><td>{{ number(s.restant) }}</td></tr></tbody></table></div><h4>Absences enregistrées sur la période</h4><div v-for="a in contextAbsences" :key="a.id" class="notification-item">{{ date(a.date_debut) }} – {{ date(a.date_fin) }} · {{ a.type }} · {{ a.statut }}</div><p v-if="!contextAbsences.length" class="muted">Aucune absence connue pour cette période.</p><h4>Congés validés dans le service</h4><div v-for="x in contextCalendar" :key="x.demandeId" class="notification-item">{{ x.prenom }} {{ x.nom }} · {{ x.typeConge }} · {{ date(x.dateDebut) }} – {{ date(x.dateFin) }}</div><p v-if="!contextCalendar.length" class="muted">Aucun autre congé validé sur la période.</p></article>
