        <article class="card"><h3>Règles de droits</h3><form class="form-grid" @submit.prevent="saveRight"><label>Type<select v-model.number="rightForm.typeCongeId" required><option v-for="t in types" :key="t.id" :value="t.id">{{ t.libelle }}</option></select></label><label>Contrat<select v-model="rightForm.typeContrat"><option :value="null">Tous</option><option>CDI</option><option>CDD</option><option>CE</option></select></label><label>Acquisition<input type="number" min="0" step="0.01" v-model.number="rightForm.regleAcquisition" required></label><label>Période<select v-model="rightForm.periodeAcquisition"><option>MOIS</option><option>ANNEE</option></select></label><label>Ancienneté min. (mois)<input type="number" min="0" v-model.number="rightForm.ancienneteMinMois"></label><label>Plafond report<input type="number" min="0" step="0.01" v-model.number="rightForm.plafondReport"></label><label>Validité report (mois)<input type="number" min="1" v-model.number="rightForm.validiteReportMois"></label><div class="actions full"><button class="button primary">{{ editingRight ? 'Enregistrer la règle' : 'Ajouter la règle' }}</button><button v-if="editingRight" type="button" class="button" @click="resetRight">Annuler</button></div></form><div class="table-wrap"><table><thead><tr><th>Type</th><th>Contrat</th><th>Acquisition</th><th>Ancienneté</th><th></th></tr></thead><tbody><tr v-for="r in rights" :key="r.id"><td>{{ typeName(r.type_conge_id) }}</td><td>{{ r.type_contrat || 'Tous' }}</td><td>{{ r.regle_acquisition }} / {{ r.periode_acquisition }}</td><td>{{ r.anciennete_min_mois }} mois</td><td><div class="row-actions"><button class="link-button" @click="editRight(r)">Modifier</button><button class="danger-link" @click="deleteRight(r)">Supprimer</button></div></td></tr></tbody></table></div></article>
      </div>
      <div class="detail-grid">
        <article class="card"><h3>Ajustement manuel de solde</h3><form class="form-grid" @submit.prevent="adjustBalance"><label>Salarié<select v-model.number="adjustForm.employeId" required><option v-for="e in employees" :key="e.id" :value="e.id">{{ employeeName(e) }}</option></select></label><label>Type<select v-model.number="adjustForm.typeCongeId" required><option v-for="t in types" :key="t.id" :value="t.id">{{ t.libelle }}</option></select></label><label>Année<input type="number" v-model.number="adjustForm.annee" min="2000" required></label><label>Quantité (+/- jours)<input type="number" step="0.5" v-model.number="adjustForm.quantite" required></label><label class="full">Motif obligatoire<textarea v-model="adjustForm.motif" required maxlength="1000"></textarea></label><div class="actions full"><button class="button primary">Enregistrer l’ajustement</button></div></form></article>
        <article class="card"><h3>Saisie d’absence</h3><form class="form-grid" @submit.prevent="createAbsence"><label>Salarié<select v-model.number="absenceForm.employeId" required><option v-for="e in employees" :key="e.id" :value="e.id">{{ employeeName(e) }}</option></select></label><label>Type<select v-model="absenceForm.type"><option>MALADIE</option><option>INJUSTIFIEE</option><option>EVENEMENT_FAMILIAL</option><option>MISSION</option><option>AUTRE</option></select></label><label>Du<input type="date" v-model="absenceForm.dateDebut" required></label><label>Au<input type="date" v-model="absenceForm.dateFin" required></label><label class="full">Commentaire<input v-model="absenceForm.commentaire"></label><div class="actions full"><button class="button primary">Enregistrer l’absence</button></div></form></article>
      </div>
      <article class="card"><div class="section-heading"><h3>Absences et justificatifs</h3><button class="button" @click="loadHrData">Actualiser</button></div><div class="table-wrap"><table><thead><tr><th>Salarié</th><th>Période</th><th>Type / statut</th><th>Qualification</th><th>Action</th></tr></thead><tbody><tr v-for="a in hrAbsences" :key="a.id"><td>{{ absenceEmployee(a) }}</td><td>{{ date(a.date_debut) }} – {{ date(a.date_fin) }}</td><td>{{ a.type }} · {{ a.statut }}</td><td>{{ a.statut_qualification || '—' }}</td><td><select v-model="a.nextType"><option>MALADIE</option><option>INJUSTIFIEE</option><option>EVENEMENT_FAMILIAL</option><option>MISSION</option><option>AUTRE</option><option>CONGE</option></select><select v-if="a.nextType==='CONGE'" v-model.number="a.typeCongeId"><option v-for="t in types.filter(x=>x.debite_solde)" :key="t.id" :value="t.id">{{ t.libelle }}</option></select><button class="button" @click="qualify(a)">Qualifier</button></td></tr><tr v-if="!hrAbsences.length"><td colspan="5" class="empty">Aucune absence à traiter.</td></tr></tbody></table></div><h4>Justificatifs déposés</h4><div class="table-wrap"><table><thead><tr><th>Salarié</th><th>Fichier</th><th>Date</th><th>Décision</th></tr></thead><tbody><tr v-for="j in evidence" :key="j.id"><td>{{ employeeById(j.employeId) }}</td><td><a :href="fileUrl(j.url)" target="_blank" rel="noreferrer">{{ j.nomFichier }}</a></td><td>{{ date(j.dateDepot) }}</td><td><div class="row-actions"><button class="button primary" @click="decideEvidence(j,true)">Valider</button><button class="danger-link" @click="decideEvidence(j,false)">Rejeter</button></div></td></tr><tr v-if="!evidence.length"><td colspan="4" class="empty">Aucun justificatif en attente.</td></tr></tbody></table></div></article>
      <div class="detail-grid"><article class="card"><h3>Rapport d’absentéisme</h3><div class="toolbar"><label>Du<input type="date" v-model="reportFrom"></label><label>Au<input type="date" v-model="reportTo"></label><button class="button" @click="loadReport">Afficher</button></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Absences</th><th>Durée moyenne</th><th>Taux</th></tr></thead><tbody><tr v-for="r in report" :key="r.departement_id"><td>{{ r.nom }}</td><td>{{ r.nb_absences }}</td><td>{{ number(r.duree_moyenne_jours) }} j</td><td>{{ r.taux_absenteisme_pct }} %</td></tr></tbody></table></div></article><article class="card"><h3>Congés à venir et calendrier global</h3><div class="toolbar"><label>Du<input type="date" v-model="calendarFrom" @change="loadGlobalCalendar"></label><label>Au<input type="date" v-model="calendarTo" @change="loadGlobalCalendar"></label><button class="button" @click="loadGlobalCalendar">Afficher</button></div><div class="table-wrap"><table><thead><tr><th>Salarié</th><th>Type</th><th>Dates</th></tr></thead><tbody><tr v-for="x in globalCalendar" :key="`${x.demandeId}-${x.employeId}`"><td>{{ x.prenom }} {{ x.nom }}</td><td>{{ x.typeConge }}</td><td>{{ date(x.dateDebut) }} – {{ date(x.dateFin) }}</td></tr><tr v-if="!globalCalendar.length"><td colspan="3" class="empty">Aucun congé validé sur la période choisie.</td></tr></tbody></table></div></article></div>
      <article class="card"><div class="section-heading"><h3>Soldes par service et reports à risque d’expiration</h3><label>Année <input type="number" v-model.number="year" min="2000" @change="loadBalanceReport"></label></div><div class="table-wrap"><table><thead><tr><th>Service</th><th>Type</th><th>Salariés</th><th>Jours restants</th><th>Reportés</th><th>À risque d’expiration</th></tr></thead><tbody><tr v-for="r in balanceReport" :key="`${r.departement_id}-${r.type_conge}`"><td>{{ r.departement }}</td><td>{{ r.type_conge }}</td><td>{{ r.nb_employes }}</td><td>{{ number(r.jours_restants) }}</td><td>{{ number(r.jours_reportes) }}</td><td>{{ number(r.jours_a_risque_expiration) }}</td></tr><tr v-if="!balanceReport.length"><td colspan="6" class="empty">Aucun solde sur cette année.</td></tr></tbody></table></div></article>
    </template>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useAuthStore } from '@/stores/auth'
import api from '@/api/axios'
import { formatApiError } from '@/utils/errors'

const auth=useAuthStore(), isManager=computed(()=>auth.role==='MANAGER'), isHr=computed(()=>['RH','ADMIN'].includes(auth.role))
const tabs=computed(()=>[{id:'mine',label:'Mon espace'},...(isManager.value||isHr.value?[{id:'approvals',label:isManager.value?'Équipe · validations':'Validation RH'}]:[]),...(isHr.value?[{id:'hr',label:'Gestion RH'}]:[])])
const active=ref('mine'), title=computed(()=>isManager.value?'Congés et absences':isHr.value?'Gestion des congés':'Mes congés')
const busy=ref(false),error=ref(''),notice=ref(''),year=ref(new Date().getFullYear()),types=ref([]),balances=ref([]),requests=ref([]),absences=ref([]),approvals=ref([]),calendar=ref([]),globalCalendar=ref([]),departments=ref([]),departmentId=ref(null),employees=ref([]),hrAbsences=ref([]),evidence=ref([]),rights=ref([]),report=ref([]),balanceReport=ref([]),contextRequest=ref(null),contextBalances=ref([]),contextAbsences=ref([]),contextCalendar=ref([]),delegations=ref([])
const today=new Date().toISOString().slice(0,10), monthStart=`${today.slice(0,7)}-01`, monthEnd=`${today.slice(0,7)}-${new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()}`
const calendarFrom=ref(today),calendarTo=ref(today.slice(0,7)+'-'+new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()),reportFrom=ref(monthStart),reportTo=ref(today)
const form=reactive({typeCongeId:'',dateDebut:'',dateFin:'',demiJourneeDebut:false,demiJourneeFin:false,motif:''})
const typeDefault=()=>({code:'',libelle:'',remunere:true,debiteSolde:true,justificatifObligatoire:false,justificatifApresJours:null,dureeMaxJours:null,demiJourneeAutorisee:true,uniteDecompte:'OUVRES',actif:true,soldeNegatifAutorise:false})
const typeForm=reactive(typeDefault()),editingType=ref(null),editingRight=ref(null),rightForm=reactive({typeCongeId:null,typeContrat:null,regleAcquisition:2.5,periodeAcquisition:'MOIS',ancienneteMinMois:0,plafondReport:0,validiteReportMois:12}),adjustForm=reactive({employeId:null,typeCongeId:null,annee:new Date().getFullYear(),quantite:0,motif:''}),absenceForm=reactive({employeId:null,type:'MALADIE',dateDebut:today,dateFin:today,commentaire:''})
const delegationForm=reactive({delegueId:null,dateDebut:today,dateFin:today})
const selectedType=computed(()=>types.value.find(t=>Number(t.id)===Number(form.typeCongeId))), selectedBalance=computed(()=>balances.value.find(s=>Number(s.typeCongeId)===Number(form.typeCongeId))), estimateDays=computed(()=>{if(!form.dateDebut||!form.dateFin||form.dateFin<form.dateDebut)return 0;let count=0;for(let d=new Date(`${form.dateDebut}T12:00:00`);d<=new Date(`${form.dateFin}T12:00:00`);d.setDate(d.getDate()+1)){if(d.getDay()!==0&&d.getDay()!==6)count++}if(form.dateDebut===form.dateFin){if(form.demiJourneeDebut!==form.demiJourneeFin)count=.5}else{if(count&&form.demiJourneeDebut)count-=.5;if(count&&form.demiJourneeFin)count-=.5}return Math.max(0,count)}),estimateRemaining=computed(()=>Number(selectedBalance.value?.restant||0)-estimateDays.value),insufficientWarning=computed(()=>selectedType.value?.debite_solde&&selectedBalance.value&&estimateRemaining.value<0?'Le solde affiché semble insuffisant. Le serveur contrôlera le solde exact à la soumission.':''),overlapWarning=computed(()=>{if(!form.dateDebut||!form.dateFin)return '';const hit=requests.value.find(d=>!['REFUSEE','ANNULEE'].includes(d.statut)&&d.date_debut<=form.dateFin&&d.date_fin>=form.dateDebut);const absence=absences.value.find(a=>a.date_debut<=form.dateFin&&a.date_fin>=form.dateDebut);return hit?'Cette période chevauche déjà votre demande #'+hit.id+'.':absence?'Cette période chevauche une absence déjà enregistrée.':''})
function number(v){return Number(v||0).toLocaleString('fr-FR',{maximumFractionDigits:2})}function date(v){if(!v)return '—';const x=String(v).slice(0,10);return new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(new Date(`${x}T12:00:00`))}function history(d){return [d.date_soumission&&`Soumise ${date(d.date_soumission)}`,d.date_validation_manager&&`Manager ${date(d.date_validation_manager)}`,d.date_validation_rh&&`RH ${date(d.date_validation_rh)}`,d.motif_refus&&`Refus : ${d.motif_refus}`].filter(Boolean).join(' · ')||'Brouillon'}function employeeName(e){return `${e.prenom||e.candidat?.prenom||''} ${e.nom||e.candidat?.nom||''} · #${e.id}`.trim()}function employeeById(id){const e=employees.value.find(x=>Number(x.id)===Number(id));return e?employeeName(e):`Employé #${id}`}function absenceEmployee(a){return employeeById(a.employe_id)}function typeName(id){return types.value.find(t=>Number(t.id)===Number(id))?.libelle||`Type #${id}`}function balanceFor(d){const s=balances.value.find(x=>Number(x.employeId)===Number(d.employe_id)&&Number(x.typeCongeId)===Number(d.type_conge_id));return s?`Solde affiché : ${number(s.restant)} j`:'Consulter le solde du salarié'}function fileUrl(path){return path?.startsWith('http')?path:`http://localhost:8080${path||''}`}
function fail(e){error.value=formatApiError(e);notice.value=''}async function loadMine(){try{const [b,r,a]=await Promise.all([api.get('/moi/soldes',{params:{annee:year.value}}),api.get('/demandes-conge',{params:{du:`${year.value}-01-01`,au:`${year.value}-12-31`}}),api.get('/moi/absences')]);balances.value=b.data;requests.value=r.data;absences.value=a.data}catch(e){fail(e)}}
async function loadTypes(){types.value=(await api.get('/conges/types')).data}
async function loadAll(){error.value='';try{await loadTypes();await loadMine();if(isManager.value||isHr.value)await loadApprovalData();if(isHr.value)await loadHrData()}catch(e){fail(e)}}
async function createRequest(){busy.value=true;try{const {data}=await api.post('/demandes-conge',{typeCongeId:form.typeCongeId,dateDebut:form.dateDebut,dateFin:form.dateFin,demiJourneeDebut:form.demiJourneeDebut,demiJourneeFin:form.demiJourneeFin,motif:form.motif});await api.post(`/demandes-conge/${data.id}/soumettre`);notice.value=`Demande #${data.id} créée et soumise.`;Object.assign(form,{typeCongeId:'',dateDebut:'',dateFin:'',demiJourneeDebut:false,demiJourneeFin:false,motif:''});await loadMine()}catch(e){fail(e)}finally{busy.value=false}}
async function submitRequest(d){try{await api.post(`/demandes-conge/${d.id}/soumettre`);notice.value='Demande soumise.';await loadMine()}catch(e){fail(e)}}async function cancelRequest(d){if(!confirm(`Annuler la demande #${d.id} ?`))return;try{await api.post(`/demandes-conge/${d.id}/annuler`);notice.value='Demande annulée.';await loadMine()}catch(e){fail(e)}}
async function approve(d){try{await api.post(`/demandes-conge/${d.id}/${isManager.value?'valider-manager':'valider-rh'}`);notice.value='Demande validée.';await loadApprovalData();await loadMine()}catch(e){fail(e)}}async function reject(d){const motif=prompt('Motif obligatoire du refus :');if(!motif?.trim())return;try{await api.post(`/demandes-conge/${d.id}/refuser`,{motif});notice.value='Demande refusée.';await loadApprovalData()}catch(e){fail(e)}}
async function loadApprovalData(){try{const params={statut:isManager.value?'SOUMISE':'VALIDEE_MANAGER'};approvals.value=(await api.get('/demandes-conge',{params})).data;departments.value=(await api.get('/departements')).data;if(isManager.value){const [team,delegated]=await Promise.all([api.get('/employes'),api.get('/delegations-validation')]);employees.value=Array.isArray(team.data)?team.data:(team.data.content||[]);delegations.value=delegated.data;const deptIds=new Set(employees.value.map(e=>e.affectationCourante?.departementId).filter(Boolean));departments.value=departments.value.filter(d=>deptIds.has(d.id));const own=employees.value.find(e=>e.email?.toLowerCase()===auth.user?.email?.toLowerCase());if(!delegationForm.delegueId)delegationForm.delegueId=employees.value.find(e=>Number(e.id)!==Number(own?.id))?.id||null}if(!departmentId.value||!departments.value.some(d=>Number(d.id)===Number(departmentId.value)))departmentId.value=departments.value[0]?.id||null;if(departmentId.value)await loadCalendar()}catch(e){fail(e)}}async function loadCalendar(){if(!departmentId.value)return;try{calendar.value=(await api.get(`/equipes/${departmentId.value}/calendrier-conges`,{params:{du:calendarFrom.value,au:calendarTo.value}})).data;if(isHr.value)globalCalendar.value=calendar.value}catch(e){fail(e)}}async function showTeamCalendar(d){const dep=departments.value[0];if(dep){departmentId.value=dep.id;await loadCalendar();active.value='approvals';notice.value=`Calendrier du service ${dep.nom} chargé pour la période affichée.`}else notice.value='Aucun service accessible.'}
async function showRequestContext(d){contextRequest.value=d;const du=String(d.date_debut).slice(0,10),au=String(d.date_fin).slice(0,10);try{const [b,a]=await Promise.all([api.get(`/employes/${d.employe_id}/soldes`,{params:{annee:du.slice(0,4)}}),api.get(`/employes/${d.employe_id}/absences`,{params:{du,au}})]);contextBalances.value=b.data;contextAbsences.value=a.data;contextCalendar.value=calendar.value.filter(x=>Number(x.demandeId)!==Number(d.id)&&x.dateDebut<=au&&x.dateFin>=du)}catch(e){fail(e)}}
async function createDelegation(){try{await api.post('/delegations-validation',delegationForm);notice.value='Délégation enregistrée.';delegations.value=(await api.get('/delegations-validation')).data}catch(e){fail(e)}}async function deleteDelegation(d){if(!confirm(`Retirer la délégation de ${d.prenom} ${d.nom} ?`))return;try{await api.delete(`/delegations-validation/${d.id}`);delegations.value=delegations.value.filter(x=>x.id!==d.id)}catch(e){fail(e)}}
async function uploadEvidence(a,event){const file=event.target.files?.[0];if(!file)return;try{const body=new FormData();body.append('fichier',file);await api.post(`/absences/${a.id}/justificatifs`,body,{headers:{'Content-Type':'multipart/form-data'}});notice.value='Justificatif déposé.';await loadMine()}catch(e){fail(e)}finally{event.target.value=''}}
async function loadHrData(){try{const [emps,as,js,ds,summary]=await Promise.all([api.get('/employes',{params:{size:200}}),api.get('/absences'),api.get('/justificatifs',{params:{statut:'DEPOSE'}}),api.get('/conges/types'),api.get('/rapports/soldes-conges',{params:{annee:year.value}})]);employees.value=Array.isArray(emps.data)?emps.data:(emps.data.content||[]);hrAbsences.value=as.data.map(a=>({...a,nextType:a.type,typeCongeId:null}));evidence.value=js.data;types.value=ds.data;balanceReport.value=summary.data;if(!adjustForm.employeId)adjustForm.employeId=employees.value[0]?.id;if(!adjustForm.typeCongeId)adjustForm.typeCongeId=types.value[0]?.id;if(!absenceForm.employeId)absenceForm.employeId=employees.value[0]?.id;rights.value=(await Promise.all(types.value.map(t=>api.get(`/conges/types/${t.id}/droits`)))).flatMap(x=>x.data)}catch(e){fail(e)}}
async function saveType(){try{if(editingType.value)await api.put(`/conges/types/${editingType.value}`,typeForm);else await api.post('/conges/types',typeForm);notice.value='Type de congé enregistré.';resetType();await loadTypes()}catch(e){fail(e)}}function editType(t){editingType.value=t.id;Object.assign(typeForm,{code:t.code,libelle:t.libelle,remunere:t.remunere,debiteSolde:t.debite_solde,justificatifObligatoire:t.justificatif_obligatoire,justificatifApresJours:t.justificatif_apres_jours,dureeMaxJours:t.duree_max_jours,demiJourneeAutorisee:t.demi_journee_autorisee,uniteDecompte:t.unite_decompte,actif:t.actif,soldeNegatifAutorise:t.solde_negatif_autorise})}function resetType(){editingType.value=null;Object.assign(typeForm,typeDefault())}async function disableType(t){if(!confirm(`Désactiver le type « ${t.libelle} » ?`))return;try{await api.delete(`/conges/types/${t.id}`);notice.value='Type de congé désactivé.';await loadTypes()}catch(e){fail(e)}}
async function loadBalanceReport(){try{balanceReport.value=(await api.get('/rapports/soldes-conges',{params:{annee:year.value}})).data}catch(e){fail(e)}}
async function saveRight(){try{if(editingRight.value)await api.put(`/conges/droits/${editingRight.value}`,rightForm);else await api.post('/conges/droits',rightForm);notice.value='Règle de droit enregistrée.';resetRight();await loadHrData()}catch(e){fail(e)}}function editRight(r){editingRight.value=r.id;Object.assign(rightForm,{typeCongeId:r.type_conge_id,typeContrat:r.type_contrat,regleAcquisition:Number(r.regle_acquisition),periodeAcquisition:r.periode_acquisition,ancienneteMinMois:r.anciennete_min_mois,plafondReport:Number(r.plafond_report),validiteReportMois:r.validite_report_mois})}function resetRight(){editingRight.value=null;Object.assign(rightForm,{typeCongeId:types.value[0]?.id||null,typeContrat:null,regleAcquisition:2.5,periodeAcquisition:'MOIS',ancienneteMinMois:0,plafondReport:0,validiteReportMois:12})}async function deleteRight(r){if(!confirm('Supprimer cette règle de droit ?'))return;try{await api.delete(`/conges/droits/${r.id}`);notice.value='Règle supprimée.';await loadHrData()}catch(e){fail(e)}}async function adjustBalance(){try{await api.post(`/employes/${adjustForm.employeId}/soldes/ajustements`,{typeCongeId:adjustForm.typeCongeId,annee:adjustForm.annee,quantite:adjustForm.quantite,motif:adjustForm.motif});notice.value='Ajustement de solde enregistré.';adjustForm.quantite=0;adjustForm.motif=''}catch(e){fail(e)}}async function createAbsence(){try{await api.post('/absences',absenceForm);notice.value='Absence enregistrée.';await loadHrData()}catch(e){fail(e)}}async function qualify(a){try{await api.post(`/absences/${a.id}/qualifier`,{type:a.nextType,typeCongeId:a.nextType==='CONGE'?a.typeCongeId:null});notice.value='Absence qualifiée.';await loadHrData()}catch(e){fail(e)}}async function decideEvidence(j,valid){let motif=null;if(!valid){motif=prompt('Motif obligatoire du rejet :');if(!motif?.trim())return}try{await api.post(`/justificatifs/${j.id}/${valid?'valider':'rejeter'}`,valid?{}:{motif});notice.value=valid?'Justificatif validé.':'Justificatif rejeté.';await loadHrData()}catch(e){fail(e)}}async function loadReport(){try{report.value=(await api.get('/rapports/absenteisme',{params:{du:reportFrom.value,au:reportTo.value}})).data}catch(e){fail(e)}}async function loadGlobalCalendar(){try{if(!departments.value.length)departments.value=(await api.get('/departements')).data;globalCalendar.value=(await Promise.all(departments.value.map(dep=>api.get(`/equipes/${dep.id}/calendrier-conges`,{params:{du:calendarFrom.value,au:calendarTo.value}})))).flatMap(x=>x.data)}catch(e){fail(e)}}
watch(active,v=>{if(v==='hr'&&isHr.value)loadHrData()});onMounted(loadAll)
</script>
